CREATE TABLE public.settings (
    key text NOT NULL,
    value text NOT NULL,
    rowid bigint NOT NULL
);

CREATE FUNCTION public.bmo_administrator() RETURNS bigint
    LANGUAGE sql STABLE
    AS $$ SELECT CAST("value" AS bigint) FROM "settings" WHERE "key" = 'users_administrator' $$;

CREATE TABLE public.document_talk (
    id bigint NOT NULL,
    document text NOT NULL,
    speaker text NOT NULL,
    text text NOT NULL,
    said_at bigint NOT NULL,
    passage text,
    heading text,
    version text,
    translated bigint DEFAULT 0 NOT NULL,
    rowid bigint GENERATED ALWAYS AS (id) STORED
);

ALTER TABLE public.document_talk ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.document_talk_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

ALTER TABLE public.settings ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.settings_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_guides (
    user_id bigint NOT NULL,
    flow text NOT NULL,
    step text NOT NULL,
    need text,
    supply_later boolean DEFAULT false NOT NULL,
    road text,
    finished_at bigint,
    left_at bigint,
    updated_at bigint NOT NULL
);

CREATE TABLE public.web_languages (
    user_name text NOT NULL,
    language text NOT NULL,
    updated_at bigint NOT NULL,
    user_id bigint
);

CREATE TABLE public.web_palettes (
    user_name text NOT NULL,
    palette text NOT NULL,
    updated_at bigint NOT NULL,
    user_id bigint,
    rowid bigint NOT NULL
);

ALTER TABLE public.web_palettes ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_palettes_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_presence_hidden (
    user_id bigint NOT NULL,
    hidden_at bigint NOT NULL
);

CREATE TABLE public.web_push_devices (
    endpoint text NOT NULL,
    user_name text NOT NULL,
    p256dh text NOT NULL,
    auth text NOT NULL,
    kinds text NOT NULL,
    refused text DEFAULT ''::text NOT NULL,
    created_at bigint NOT NULL,
    last_sent_at bigint,
    rowid bigint NOT NULL,
    user_id bigint DEFAULT public.bmo_administrator()
);

ALTER TABLE public.web_push_devices ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_push_devices_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_room_reads (
    user_name text NOT NULL,
    chat_id bigint NOT NULL,
    message_id bigint,
    sent_at bigint NOT NULL,
    row_order bigint NOT NULL,
    created_at bigint NOT NULL,
    read_at bigint NOT NULL,
    user_id bigint,
    rowid bigint NOT NULL
);

ALTER TABLE public.web_room_reads ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_room_reads_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_tab_states (
    user_name text NOT NULL,
    screen text NOT NULL,
    state text NOT NULL,
    updated_at bigint NOT NULL,
    rowid bigint NOT NULL,
    user_id bigint DEFAULT public.bmo_administrator()
);

ALTER TABLE public.web_tab_states ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_tab_states_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_themes (
    user_name text NOT NULL,
    theme text NOT NULL,
    updated_at bigint NOT NULL,
    user_id bigint,
    rowid bigint NOT NULL
);

ALTER TABLE public.web_themes ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_themes_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE public.web_users (
    name text NOT NULL,
    password_hash text NOT NULL,
    created_at bigint NOT NULL,
    rowid bigint NOT NULL
);

ALTER TABLE public.web_users ALTER COLUMN rowid ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.web_users_rowid_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

ALTER TABLE ONLY public.document_talk
    ADD CONSTRAINT document_talk_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.settings
    ADD CONSTRAINT settings_pkey PRIMARY KEY (key);

ALTER TABLE ONLY public.settings
    ADD CONSTRAINT settings_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_guides
    ADD CONSTRAINT web_guides_pkey PRIMARY KEY (user_id);

ALTER TABLE ONLY public.web_languages
    ADD CONSTRAINT web_languages_pkey PRIMARY KEY (user_name);

ALTER TABLE ONLY public.web_palettes
    ADD CONSTRAINT web_palettes_pkey PRIMARY KEY (user_name);

ALTER TABLE ONLY public.web_palettes
    ADD CONSTRAINT web_palettes_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_presence_hidden
    ADD CONSTRAINT web_presence_hidden_pkey PRIMARY KEY (user_id);

ALTER TABLE ONLY public.web_push_devices
    ADD CONSTRAINT web_push_devices_pkey PRIMARY KEY (endpoint);

ALTER TABLE ONLY public.web_push_devices
    ADD CONSTRAINT web_push_devices_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_room_reads
    ADD CONSTRAINT web_room_reads_pkey PRIMARY KEY (user_name, chat_id);

ALTER TABLE ONLY public.web_room_reads
    ADD CONSTRAINT web_room_reads_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_tab_states
    ADD CONSTRAINT web_tab_states_pkey PRIMARY KEY (user_name, screen);

ALTER TABLE ONLY public.web_tab_states
    ADD CONSTRAINT web_tab_states_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_themes
    ADD CONSTRAINT web_themes_pkey PRIMARY KEY (user_name);

ALTER TABLE ONLY public.web_themes
    ADD CONSTRAINT web_themes_rowid_key UNIQUE (rowid);

ALTER TABLE ONLY public.web_users
    ADD CONSTRAINT web_users_pkey PRIMARY KEY (name);

ALTER TABLE ONLY public.web_users
    ADD CONSTRAINT web_users_rowid_key UNIQUE (rowid);

CREATE INDEX document_talk_document ON public.document_talk USING btree (document, id);

CREATE INDEX web_push_devices_user ON public.web_push_devices USING btree (user_name);
